@import url('https://fonts.googleapis.com/css2?family=Big+Shoulders:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Golden State Warriors DNA — royal bay night, bridge gold */
.theme-golden-state-warriors {
  --bg: oklch(0.268 0.088 262.0);
  --surface: oklch(0.318 0.098 259.9);
  --surface-2: oklch(0.368 0.110 259.1);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.755 0.050 263.1);
  --accent: oklch(0.857 0.165 86.5);
  --accent-fg: oklch(0.268 0.088 262.0);
  --accent-2: oklch(1.000 0 0);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.615 0.190 27.8);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Big Shoulders", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-golden-state-warriors h1,
.theme-golden-state-warriors h2,
.theme-golden-state-warriors h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-golden-state-warriors { --font-ui: var(--font-display); }
.theme-golden-state-warriors h1, .theme-golden-state-warriors h2 { text-transform: uppercase; font-weight: 800; }
.theme-golden-state-warriors button { text-transform: uppercase; letter-spacing: 0.08em; font-weight: 700; }

.theme-golden-state-warriors h1 { color: var(--accent); }
.theme-golden-state-warriors h1::after { content: ""; display: block; height: 6px; width: 7rem; margin-top: 0.6rem; background: var(--accent); border-radius: 999px 999px 0 0; clip-path: ellipse(50% 100% at 50% 100%); }

/* depth */
.theme-golden-state-warriors ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-golden-state-warriors a { color: var(--accent); text-decoration-color: color-mix(in oklab, var(--accent) 50%, transparent); text-underline-offset: 3px; }
.theme-golden-state-warriors a:hover { color: #ffffff; text-decoration-color: var(--accent); text-decoration-thickness: 2px; }
/* bridge deck: heavy gold rail over hairline */
.theme-golden-state-warriors thead th { font-family: var(--font-display); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.8em; color: var(--fg-muted); background: oklch(0.235 0.080 262); border-top: 1px solid var(--line); border-bottom: 3px solid var(--accent); }
.theme-golden-state-warriors td { border-bottom: 1px solid var(--line); }
.theme-golden-state-warriors tbody tr:hover { background: oklch(0.857 0.165 86.5 / 8%); }
.theme-golden-state-warriors input, .theme-golden-state-warriors select, .theme-golden-state-warriors textarea { background: oklch(0.23 0.078 262); border: 1px solid var(--line); caret-color: var(--accent); }
.theme-golden-state-warriors input:focus-visible, .theme-golden-state-warriors select:focus-visible, .theme-golden-state-warriors textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px oklch(0.857 0.165 86.5 / 25%); }
/* circle-logo roundel kbd */
.theme-golden-state-warriors kbd { font-family: var(--font-display); font-weight: 700; background: oklch(0.22 0.075 262); color: var(--accent); border: 2px solid var(--accent); border-radius: var(--radius-pill); padding: 0.1em 0.55em; }
.theme-golden-state-warriors ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-golden-state-warriors ::-webkit-scrollbar-track { background: oklch(0.23 0.078 262); }
.theme-golden-state-warriors ::-webkit-scrollbar-thumb { background: oklch(0.66 0.13 87); border: 2px solid oklch(0.23 0.078 262); border-radius: 999px; }
.theme-golden-state-warriors ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-golden-state-warriors .label-caps { color: var(--accent); font-weight: 700; }
/* physical: suspension cables — fine vertical strands inside featured borders */
.theme-golden-state-warriors .themed-border { border-color: color-mix(in oklab, var(--accent) 50%, transparent); background-image: repeating-linear-gradient(90deg, oklch(1 0 0 / 4%) 0 1px, transparent 1px 16px); }
.theme-golden-state-warriors button:hover { box-shadow: inset 0 -3px 0 var(--accent), var(--shadow-1); }
.theme-golden-state-warriors button:active { transform: translateY(1px); }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-golden-state-warriors.alt-mode {
  --bg: oklch(0.985 0 0);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.953 0.003 286.3);
  --fg: oklch(0.206 0.006 285.9);
  --fg-muted: oklch(0.478 0.016 285.8);
  --accent: oklch(0.396 0.128 261.9);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.857 0.165 86.5);
  --line: oklch(0.914 0.005 286.3);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: none;
}
.theme-golden-state-warriors.alt-mode h1 { background: none; -webkit-background-clip: initial; background-clip: initial; color: #1d428a; -webkit-text-stroke: 0; }
.theme-golden-state-warriors.alt-mode thead th { color: oklch(0.857 0.165 86.5); background: oklch(0.30 0.10 262); border-bottom-color: oklch(0.857 0.165 86.5); }
.theme-golden-state-warriors.alt-mode input, .theme-golden-state-warriors.alt-mode select, .theme-golden-state-warriors.alt-mode textarea { background: oklch(1 0 0); border-color: var(--line); }
.theme-golden-state-warriors.alt-mode kbd { background: oklch(1 0 0); color: oklch(0.396 0.128 261.9); border-color: oklch(0.396 0.128 261.9); }
.theme-golden-state-warriors.alt-mode ::-webkit-scrollbar-track { background: oklch(0.95 0.005 286); }
.theme-golden-state-warriors.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.55 0.11 262); border-color: oklch(0.95 0.005 286); }
.theme-golden-state-warriors.alt-mode tbody tr:hover { background: oklch(0.396 0.128 261.9 / 7%); }
.theme-golden-state-warriors.alt-mode .themed-border { background-image: repeating-linear-gradient(90deg, oklch(0.268 0.088 262 / 5%) 0 1px, transparent 1px 16px); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
